 IF EXISTS (
  (SELECT slug,id,is_published,published_at,updated_at FROM public.stack127_pages WHERE is_published AND NOT (slug='ad-networks' OR slug LIKE 'ad-networks/%')
   EXCEPT SELECT slug,id,is_published,published_at,updated_at FROM directory_public_routes_before)
  UNION ALL
  (SELECT slug,id,is_published,published_at,updated_at FROM directory_public_routes_before
   EXCEPT SELECT slug,id,is_published,published_at,updated_at FROM public.stack127_pages WHERE is_published AND NOT (slug='ad-networks' OR slug LIKE 'ad-networks/%'))
 ) THEN
  RAISE EXCEPTION 'An unrelated published route changed';
 END IF;
END;
$publication_readback$;
DROP TABLE directory_registry_seed;
DROP TABLE directory_public_routes_before;

DO $identity_sequence_guard$
DECLARE highest_id bigint; sequence_value bigint;
BEGIN
 SELECT max("id") INTO highest_id FROM public."ad_networks";
 SELECT last_value INTO sequence_value FROM public."ad_networks_id_seq";
 IF highest_id IS NOT NULL AND highest_id > sequence_value THEN
  PERFORM setval('public.ad_networks_id_seq'::regclass,highest_id,true);
 END IF;
END;
$identity_sequence_guard$;
DO $identity_sequence_guard$
DECLARE highest_id bigint; sequence_value bigint;
BEGIN
 SELECT max("id") INTO highest_id FROM public."ad_network_publishers";
 SELECT last_value INTO sequence_value FROM public."ad_network_publishers_id_seq";
 IF highest_id IS NOT NULL AND highest_id > sequence_value THEN
  PERFORM setval('public.ad_network_publishers_id_seq'::regclass,highest_id,true);
 END IF;
END;
$identity_sequence_guard$;
NOTIFY pgrst, 'reload schema';
COMMIT;
